import{_ as n,a0 as u,w as r,s as l,ao as o,I as a,x as p,a1 as d,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"apt 的 update 和 upgrade 命令的區別是什麼？ | LCTT x X-CMD","titleTemplate":false,"description":"apt 的 update 和 upgrade 命令的區別是什麼？ | LCTT (202209) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"apt 的 update 和 upgrade 命令的區別是什麼？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"apt 的 update 和 upgrade 命令的區別是什麼？ | LCTT (202209) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202209/20220824 sudo apt update vs upgrade- What-s the Difference-","title":"apt 的 update 和 upgrade 命令的區別是什麼？","tag":"202209","desc":""},"relativePath":"202209/20220824 sudo apt update vs upgrade- What-s the Difference-.md","filePath":"[post].md"}'),g={name:"202209/20220824 sudo apt update vs upgrade- What-s the Difference-.md"};function i(m,t,f,c,b,T){const e=u("Link");return r(),l("div",null,[t[40]||(t[40]=o('<h1 id="apt-的-update-和-upgrade-命令的區別是什麼" tabindex="-1">apt 的 update 和 upgrade 命令的區別是什麼？ <a class="header-anchor" href="#apt-的-update-和-upgrade-命令的區別是什麼" aria-label="Permalink to “apt 的 update 和 upgrade 命令的區別是什麼？”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202209/02/224416uecz5x75yalc0axc.jpg" alt=""></p><p>如果想讓你的 Ubuntu 或者 Debian 系統保持更新，要用 <code>sudo apt update</code> 和 <code>sudo apt upgrade</code> 命令組合。</p><p>一些以前的教程也會提到 <code>sudo apt-get update</code> 和 <code>sudo apt-get upgrade</code>。</p><p><code>apt</code> 和 <code>apt-get</code> 命令運行起來幾乎一樣，除了一些細微的差別，後面我會討論。</p><p>我們首先討論一下 <code>update</code> 和 <code>upgrade</code> 的區別。這兩個難道不是一樣的嗎？</p><h3 id="apt-的-update-和-upgrade-的區別" tabindex="-1">apt 的 update 和 upgrade 的區別 <a class="header-anchor" href="#apt-的-update-和-upgrade-的區別" aria-label="Permalink to “apt 的 update 和 upgrade 的區別”">​</a></h3><p>儘管聽上去運行 <code>apt update</code> 可以給你一個包的最新版本，然而這並不正確。<code>update</code> 命令只會獲得系統上所有包的最新信息，並不會下載或者安裝任何一個包。而是 <code>apt upgrade</code> 命令來把這些包下載和升級到最新版本。</p>',8)),a("p",null,[t[1]||(t[1]=p("還是有點困惑？讓我來接着解釋。我建議閲讀 ",-1)),d(e,{href:"https://itsfoss.com/package-manager/"},{default:s(()=>[...t[0]||(t[0]=[p("包管理器的概念",-1)])]),_:1}),t[2]||(t[2]=p("。這個會幫你更好的理解這些東西。",-1))]),t[41]||(t[41]=o('<p><img src="https://itsfoss.com/wp-content/uploads/2020/10/linux-package-manager-explanation.png" alt="Linux Package Manager Explanation"></p><p>基本上，你的系統圍繞着一個所有可用包的資料庫（緩存）工作。注意，這個緩存（或者資料庫）並不包含這些包本身，僅僅是關於包的元數據（版本、倉庫、依賴等）。</p><p>如果你不更新這個資料庫，系統就不會知道是否有更新的版本。</p><p>當你運行 <code>apt update</code> 或者 <code>apt-get update</code> 命令，它會獲取這些包的最新元數據（包的版本等）。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/apt-update.png" alt="apt update"></p><p>這時候本地緩存就被更新了，有一些包可以升級。用 <code>sudo apt upgrade</code> 可以升級所有（可升級的）包。</p><p>它會顯示要升級的包，並且通過回車（默認選擇是 <code>Y</code>）或者按下 <code>Y</code> 鍵進行確認。要在這個階段取消升級，可以按下 <code>N</code>。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/apt-upgrade.png" alt="apt upgrade"></p><p>下面這些可能會幫助你記憶：</p><ul><li><code>apt update</code>：更新包緩存（可以知道包的哪些版本可以被安裝或升級）</li><li><code>apt upgrade</code>：升級包到最新版本</li></ul><p>因為有一些管理員命令，需要作為 root 運行。因此需要使用 <code>sudo</code> 配合其他命令。<code>sudo</code> 使你能夠作為 root 在 Ubuntu 和 Debian 上運行命令。</p><p>既然理解了 <code>update</code> 和 <code>upgrade</code> 是如何一起運行的，我們接下來來討論一下 <code>apt</code> 和 <code>apt-get</code> 的用法。</p><h3 id="apt-還是-apt-get-應該用哪個" tabindex="-1">apt 還是 apt-get？應該用哪個？ <a class="header-anchor" href="#apt-還是-apt-get-應該用哪個" aria-label="Permalink to “apt 還是 apt-get？應該用哪個？”">​</a></h3><p>Debian 和 Ubuntu 使用的是 APT 包管理系統。不要和 <code>apt</code> 命令弄混了。</p><p>有許多和 APT 包管理交互的命令；<code>apt-get</code>、<code>apt</code>、<code>dpkg</code>、<code>aptitude</code> 等。</p><p>這裏面最受歡迎的就是 <code>apt-get</code> 命令。它是一個<ruby>低層級<rt>low-level</rt></ruby>且功能豐富的命令。<code>apt</code> 是 <code>apt-get</code> 命令的一個更新而更簡單的版本。</p>',16)),a("p",null,[t[4]||(t[4]=p("可以讀一下這篇文章來 ",-1)),d(e,{href:"https://itsfoss.com/apt-get-upgrade-vs-dist-upgrade/"},{default:s(()=>[...t[3]||(t[3]=[p("瞭解 atp 和 apt-get 命令的不同",-1)])]),_:1}),t[5]||(t[5]=p("。下面重點討論這些命令中 ",-1)),t[6]||(t[6]=a("code",null,"update",-1)),t[7]||(t[7]=p(" 和 ",-1)),t[8]||(t[8]=a("code",null,"upgrade",-1)),t[9]||(t[9]=p(" 選項的區別。",-1))]),t[42]||(t[42]=o(`<h4 id="apt-update-vs-apt-get-update" tabindex="-1">apt update vs apt-get update <a class="header-anchor" href="#apt-update-vs-apt-get-update" aria-label="Permalink to “apt update vs apt-get update”">​</a></h4><p><code>apt-get update</code> 和 <code>apt update</code> 做的是同樣的事，都是更新本地包緩存，這樣的話你的系統就知道有哪些包的版本是可用的。</p><p>從技術上講，其實並沒有區別。然而，<code>apt update</code> 在一個方面比 <code>apt-get update</code> 做的好，<strong>它會告訴你可升級的包的數量</strong>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Hit:15 https://ppa.launchpadcontent.net/slimbook/slimbook/ubuntu jammy InRelease</span></span>
<span class="line"><span>Fetched 213 kB in 4s (55.8 kB/s)</span></span>
<span class="line"><span>Reading package lists... Done</span></span>
<span class="line"><span>Building dependency tree... Done</span></span>
<span class="line"><span>Reading state information... Done</span></span>
<span class="line"><span>6 packages can be upgraded. Run &#39;apt list --upgradable&#39; to see them.</span></span></code></pre></div><p><code>apt-get update</code> 甚至不會告訴你包是否可以升級。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/apt-get-update.png" alt="apt get update"></p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/apt-update-output.png" alt="apt update output"></p>`,7)),a("p",null,[t[11]||(t[11]=p("從 ",-1)),t[12]||(t[12]=a("code",null,"apt",-1)),t[13]||(t[13]=p(" 中可以看到 ",-1)),d(e,{href:"https://itsfoss.com/apt-list-upgradable/"},{default:s(()=>[...t[10]||(t[10]=[p("列出可升級的包",-1)])]),_:1}),t[14]||(t[14]=p("，而 ",-1)),t[15]||(t[15]=a("code",null,"apt-get",-1)),t[16]||(t[16]=p(" 甚至沒有這個選項。",-1))]),t[43]||(t[43]=o(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt list --upgradable</span></span>
<span class="line"><span>Listing... Done</span></span>
<span class="line"><span>fprintd/jammy-updates 1.94.2-1ubuntu0.22.04.1 amd64 [upgradable from: 1.94.2-1]</span></span>
<span class="line"><span>gnome-control-center-data/jammy-updates,jammy-updates 1:41.7-0ubuntu0.22.04.4 all [upgradable from: 1:41.7-0ubuntu0.22.04.1]</span></span>
<span class="line"><span>gnome-control-center-faces/jammy-updates,jammy-updates 1:41.7-0ubuntu0.22.04.4 all [upgradable from: 1:41.7-0ubuntu0.22.04.1]</span></span>
<span class="line"><span>gnome-control-center/jammy-updates 1:41.7-0ubuntu0.22.04.4 amd64 [upgradable from: 1:41.7-0ubuntu0.22.04.1]</span></span>
<span class="line"><span>libpam-fprintd/jammy-updates 1.94.2-1ubuntu0.22.04.1 amd64 [upgradable from: 1.94.2-1]</span></span>
<span class="line"><span>vivaldi-stable/stable 5.4.2753.40-1 amd64 [upgradable from: 5.4.2753.37-1]</span></span></code></pre></div><p>現在來比較一下兩個命令中 <code>upgrade</code> 的選項。</p><h4 id="apt-upgrade-vs-apt-get-upgrade" tabindex="-1">apt upgrade vs apt-get upgrade <a class="header-anchor" href="#apt-upgrade-vs-apt-get-upgrade" aria-label="Permalink to “apt upgrade vs apt-get upgrade”">​</a></h4><p><code>apt-get upgrade</code> 和 <code>apt upgrade</code> 命令根據本地包緩存（通過 <code>update</code> 命令更新）的數據，安裝可升級包的最新版本。</p><p>然而，<code>apt upgrade</code> 命令會做兩件與 <code>apt-get upgrade</code> 不同的事情。</p>`,5)),a("p",null,[t[18]||(t[18]=a("code",null,"apt upgrade",-1)),t[19]||(t[19]=p(" 命令可以升級 Linux 內核版本，",-1)),t[20]||(t[20]=a("code",null,"apt-get upgrade",-1)),t[21]||(t[21]=p(" 不能。",-1)),t[22]||(t[22]=a("code",null,"apt-get",-1)),t[23]||(t[23]=p(" 命令需要使用 ",-1)),d(e,{href:"https://itsfoss.com/apt-get-upgrade-vs-dist-upgrade/"},{default:s(()=>[...t[17]||(t[17]=[p("apt-get dist-upgrade",-1)])]),_:1}),t[24]||(t[24]=p(" 來升級內核版本。",-1))]),t[44]||(t[44]=o('<p><img src="https://itsfoss.com/wp-content/uploads/2022/08/apt-get-upgrade.png" alt="apt-get upgrade command cannot upgrade Linux kernel version"></p><p>這是因為升級內核版本意味着安裝一個全新的包。<code>apt-get upgrade</code> 命令不能安裝一個新的包。它只能升級現有的包。</p><p><code>apt upgrade</code> 比 <code>apt-get</code> 做的好的另一件小事是，它會在底部<strong>顯示一個進度條</strong>。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/apt-upgrade-progress-bar.png" alt="apt upgrade progress bar"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p><code>update</code> 和 <code>upgrade</code> 兩個詞很相似，這就是為什麼很多新用户會感到困惑。有時候，我覺得 <code>apt update</code> 命令應該和 <code>apt upgrade</code> 命令合併。</p><p>我意思是 <code>upgrade</code>（所有已安裝的包）和 <code>update</code>（本地包元數據緩存）一起完成工作。為什麼要有兩個分開的命令呢？把這兩個領命合成一個 <code>upgrade</code> 命令吧。Fedora 就是這樣對 DNF 命令進行了改進。不過這只是我的觀點。</p><p>我希望這篇文章可以解釋一些關於 <code>apt-get update</code>、<code>apt-get upgrade</code> 和 <code>apt update</code> 以及 <code>apt upgrade</code> 命令的問題。</p><p>如果有任何問題，請與我聯繫。</p><hr>',10)),a("p",null,[t[26]||(t[26]=p("via: ",-1)),d(e,{href:"https://itsfoss.com/apt-update-vs-upgrade/"},{default:s(()=>[...t[25]||(t[25]=[p("https://itsfoss.com/apt-update-vs-upgrade/",-1)])]),_:1})]),a("p",null,[t[31]||(t[31]=p("作者：",-1)),d(e,{href:"https://itsfoss.com/"},{default:s(()=>[...t[27]||(t[27]=[p("Abhishek Prakash",-1)])]),_:1}),t[32]||(t[32]=p(" 選題：",-1)),d(e,{href:"https://github.com/lkxed"},{default:s(()=>[...t[28]||(t[28]=[p("lkxed",-1)])]),_:1}),t[33]||(t[33]=p(" 譯者：",-1)),d(e,{href:"https://github.com/Yufei-Yan"},{default:s(()=>[...t[29]||(t[29]=[p("Yufei-Yan",-1)])]),_:1}),t[34]||(t[34]=p(" 校對：",-1)),d(e,{href:"https://github.com/wxy"},{default:s(()=>[...t[30]||(t[30]=[p("wxy",-1)])]),_:1})]),a("p",null,[t[37]||(t[37]=p("本文由 ",-1)),d(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[35]||(t[35]=[p("LCTT",-1)])]),_:1}),t[38]||(t[38]=p(" 原創編譯，",-1)),d(e,{href:"https://linux.cn/"},{default:s(()=>[...t[36]||(t[36]=[p("Linux中國",-1)])]),_:1}),t[39]||(t[39]=p(" 榮譽推出",-1))])])}const C=n(g,[["render",i]]);export{v as __pageData,C as default};
